smart.css:
.smc-root {
  color: var(--smc-text);
  background: var(--smc-bg);
  font-family: var(--smc-font-body);
  font-size: 16px;
  line-height: 1.75;
}

.smc-root h2,
.smc-root h3 {
  color: var(--smc-primary);
  font-family: var(--smc-font-heading);
  font-weight: 700;
  line-height: 1.3;
}

.smc-root h2 { font-size: clamp(25px, 4vw, 36px); }
.smc-root h3 { font-size: 19px; }
.smc-root p { margin: 0 0 14px; }
.smc-root a { color: var(--smc-accent); text-decoration: none; }
.smc-root a:hover { text-decoration: underline; }

.smc-eyebrow {
  color: var(--smc-accent);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .12em;
  margin: 0 0 8px;
}

.smc-intro {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 24px;
  padding: 28px 20px;
  background: color-mix(in srgb, var(--smc-primary) 7%, var(--smc-bg));
  border-radius: var(--smc-radius);
}

.smc-intro-copy h2 { margin: 0 0 18px; }
.smc-intro-media { margin: 0; }
.smc-intro-media img {
  display: block;
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  border-radius: var(--smc-radius);
}
.smc-intro-media figcaption {
  color: var(--smc-muted);
  font-size: 13px;
  line-height: 1.5;
  margin-top: 8px;
  text-align: center;
}

.smc-section { padding: 48px 0 0; }
.smc-section-heading { max-width: 700px; margin-bottom: 22px; }
.smc-section-heading h2,
.smc-spec-copy h2 { margin: 0 0 12px; }

.smc-feature-grid,
.smc-use-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 14px;
}

.smc-feature-card {
  padding: 22px;
  background: var(--smc-surface);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
}
.smc-feature-number {
  display: block;
  color: var(--smc-accent);
  font-size: 13px;
  font-weight: 700;
  margin-bottom: 12px;
}
.smc-feature-card h3 { margin: 0 0 8px; }
.smc-feature-card p { color: var(--smc-muted); margin: 0; }

.smc-spec-wrap {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 24px;
}
.smc-table-scroll { overflow-x: auto; }
.smc-spec-table {
  width: 100%;
  min-width: 520px;
  border-collapse: separate;
  border-spacing: 0;
  overflow: hidden;
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
}
.smc-spec-table th,
.smc-spec-table td {
  padding: 13px 16px;
  border-bottom: 1px solid var(--smc-border);
  text-align: left;
  vertical-align: top;
}
.smc-spec-table th {
  color: var(--smc-bg);
  background: var(--smc-primary);
  font-weight: 700;
}
.smc-spec-table td:first-child { width: 34%; font-weight: 700; }
.smc-spec-table tr:last-child td { border-bottom: 0; }

.smc-use-card {
  overflow: hidden;
  background: var(--smc-surface);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
}
.smc-use-card img {
  display: block;
  width: 100%;
  height: 240px;
  object-fit: cover;
}
.smc-use-copy { padding: 20px; }
.smc-use-copy h3 { margin: 0 0 8px; }
.smc-use-copy p { color: var(--smc-muted); margin: 0; }

.smc-care {
  margin-top: 48px;
  padding: 30px 20px;
  background: color-mix(in srgb, var(--smc-accent) 6%, var(--smc-bg));
  border-radius: var(--smc-radius);
}
.smc-steps { list-style: none; margin: 0; padding: 0; }
.smc-steps li {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr);
  gap: 14px;
  padding: 16px 0;
  border-bottom: 1px solid var(--smc-border);
}
.smc-step-index {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  color: var(--smc-bg);
  background: var(--smc-accent);
  border-radius: 50%;
  font-weight: 700;
}
.smc-steps h3 { margin: 2px 0 6px; }
.smc-steps p { color: var(--smc-muted); margin: 0; }
.smc-note {
  margin-top: 20px;
  padding: 18px;
  background: var(--smc-bg);
  border-left: 4px solid var(--smc-accent);
  border-radius: var(--smc-radius);
}
.smc-note p { margin: 6px 0 0; }

.smc-faq details {
  border-top: 1px solid var(--smc-border);
  padding: 15px 0;
}
.smc-faq details:last-child { border-bottom: 1px solid var(--smc-border); }
.smc-faq summary {
  color: var(--smc-primary);
  font-family: var(--smc-font-heading);
  font-weight: 700;
  cursor: pointer;
}
.smc-faq details p { color: var(--smc-muted); margin: 12px 0 0; }

.smc-related {
  margin-top: 48px;
  padding: 22px;
  background: var(--smc-surface);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
}
.smc-related strong { color: var(--smc-primary); }
.smc-related-links { display: flex; flex-wrap: wrap; gap: 10px 18px; margin-top: 10px; }

.smc-root.smc-js [data-smc-reveal] {
  opacity: 0;
  transform: translateY(14px);
  transition: opacity .45s ease, transform .45s ease;
}
.smc-root.smc-js [data-smc-reveal].is-visible { opacity: 1; transform: none; }

@container smc (min-width: 700px) {
  .smc-intro { grid-template-columns: 1.02fr .98fr; padding: 34px; align-items: center; }
  .smc-feature-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .smc-spec-wrap { grid-template-columns: .8fr 1.2fr; align-items: start; }
  .smc-use-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .smc-care { padding: 36px; }
}

@container smc (max-width: 420px) {
  .smc-root { font-size: 15px; }
  .smc-section { padding-top: 36px; }
  .smc-intro { padding: 22px 16px; }
  .smc-care { padding: 24px 16px; }
  .smc-use-card img { height: 205px; }
}

